UPDATE tools SET choose_if = $t12ci$["✅ אתם רוצים AI Coding פתוח חינם עם בחירת מודל חופשית", "✅ Continue.dev תומך ב-Ollama, Claude, GPT-4 ועוד", "✅ פרטיות – הקוד שלכם נשאר מקומי עם מודלים מקומיים", "✅ Extension ל-VS Code ו-JetBrains חינמי לחלוטין"]$t12ci$::JSONB, faq = $t12fq$[{"q": "מה זה Continue.dev?", "a": "Continue.dev הוא עוזר AI לכתיבת קוד Open Source ל-VS Code ו-JetBrains. עובד כמו Copilot אך אתם בוחרים את המודל – OpenAI, Anthropic, Ollama ועוד."}, {"q": "Continue.dev חינמי?", "a": "Continue.dev חינמי ו-Open Source. אתם משלמים רק עבור המודל – Claude API, OpenAI API, או חינם עם Ollama. GitHub Copilot מ-$10/חודש."}, {"q": "Continue.dev עם מודלים מקומיים?", "a": "Continue.dev עם DeepSeek Coder ו-Codestral דרך Ollama מצוין להשלמת קוד. למשימות מורכבות, מודלים בענן עדיין עדיפים. מצוין לפרטיות ולחיסכון בעלויות."}, {"q": "Continue.dev לעומת GitHub Copilot?", "a": "Copilot בוגר עם ביצועים עקביים. Continue.dev גמיש, חינמי ומכבד פרטיות. Copilot לביצועים מקסימליים; Continue.dev למפתחים שרוצים גמישות ופרטיות."}]$t12fq$::JSONB WHERE slug = 'continue-dev' AND lang = 'he';
UPDATE tools SET choose_if = $t13ci$["✅ אתם לומדים קורסים ב-Coursera ורוצים AI שמסביר חומר מהקורס", "✅ Coursera Coach עוזר בחומר ספציפי לקורסים שהירשמתם", "✅ מתאים לאנשי מקצוע שלומדים Data Science, AI, Business ועוד", "✅ AI שמותאם לתכנית הלימודים של Coursera"]$t13ci$::JSONB, faq = $t13fq$[{"q": "Coursera Coach לעומת Khanmigo?", "a": "Coursera Coach ל-learners בקורסי Coursera. Khanmigo לתלמידים בחומר בית-ספרי. Coursera לאנשי מקצוע; Khanmigo לתלמידים ובגרויות."}, {"q": "Coursera Coach חינמי?", "a": "Coursera Coach כלול ב-Coursera Plus ($59/חודש) ובקורסים פרטיים. Khanmigo ב-$9/חודש."}, {"q": "Coursera לישראל – האם יש תוכן בעברית?", "a": "Coursera באנגלית בעיקר עם כתוביות מתורגמות לחלק מהקורסים. Khanmigo באנגלית; Khan Academy מציע חלק מהתוכן בעברית."}, {"q": "Khanmigo לבגרויות ישראליות?", "a": "Khanmigo יכול לעזור בחומר בגרות מתמטיקה, מדעים ואנגלית. עבור בגרויות בעברית הייעודיות לישראל – מומלץ לבדוק תאימות."}]$t13fq$::JSONB WHERE slug = 'coursera-coach' AND lang = 'he';
UPDATE tools SET choose_if = $t14ci$["✅ אתם רוצים עורך AI ראשון עם כלי Agentic Coding מתקדמים", "✅ Cursor Composer מייצר ושינוי קבצים מרובים בבת אחת", "✅ תאים עם VS Code – כל Extensions וההגדרות עובדים", "✅ העורך הנפוץ ביותר עם קהילה גדולה"]$t14ci$::JSONB, faq = $t14fq$[{"q": "Zed לעומת Cursor – מה עדיף?", "a": "Cursor בוגר יותר עם Agentic Features חזקים. Zed מהיר יותר עם Multiplayer ייחודי. AI Coding – Cursor; ביצועים ושיתוף – Zed."}, {"q": "Zed חינמי?", "a": "Zed חינמי ו-Open Source. AI Features ב-Zed עשויים לדרוש API. Cursor מציע תוכנית חינמית; Pro ב-$20/חודש."}, {"q": "Zed Extensions – האם יש?", "a": "Zed לא תואם ל-VS Code Extensions. יש ל-Zed system Extensions משלו שעדיין קטן ממערכת VS Code. גדל בהדרגה."}, {"q": "Zed ל-macOS – כמה מוטב?", "a": "Zed פותח במקור ל-macOS ומשתמש ב-Metal API לביצועים מיטביים. Linux נתמך; Windows בפיתוח."}]$t14fq$::JSONB WHERE slug = 'cursor' AND lang = 'he';
UPDATE tools SET choose_if = $t15ci$["✅ אתם עובדים ב-Figma ורוצים AI ישירות בתוך הכלי", "✅ Figma AI מייצר Wireframes ו-Mockups מתיאורים", "✅ Figma Make הופך עיצוב לקוד React", "✅ AI לכתיבת Copy, תרגום ו-Rename שכבות בתוך Figma"]$t15ci$::JSONB, faq = $t15fq$[{"q": "Claude לעיצוב לעומת Figma AI?", "a": "Claude מצוין לתכנון, משוב ותיעוד. Figma AI פועל בתוך Figma ליצירת Mockups ו-Wireframes. Claude ל-UX Thinking; Figma AI לביצוע בכלי."}, {"q": "Figma AI כמה עולה?", "a": "Figma AI כלול בתוכניות Figma; Professional מ-$15/editor/חודש. Claude Pro ב-$20/חודש."}, {"q": "Claude יכול לקרוא Figma Files?", "a": "Claude לא מתחבר ישירות ל-Figma. ניתן להדביק Screenshots או לתאר עיצובים בטקסט. ל-Figma integration ישיר – השתמשו ב-Figma AI."}, {"q": "Figma Make – מה זה?", "a": "Figma Make הופך עיצובי Figma לקוד React/HTML פונקציונלי. עדיין בשלבי Beta, אך מציע bridge בין עיצוב לפיתוח."}]$t15fq$::JSONB WHERE slug = 'figma-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t16ci$["✅ אתם משקיעים פונדמנטליים שרוצים לשאול שאלות על דוחות כספיים", "✅ Finchat מנתח 10-K, Earnings Calls ודוחות בשפה טבעית", "✅ Due diligence מהיר ללא קריאת מאות עמודים ידנית", "✅ מתאים למשקיעים לטווח ארוך שמנתחים עסקים"]$t16ci$::JSONB, faq = $t16fq$[{"q": "TradingView לעומת Finchat – מה ההבדל?", "a": "TradingView לניתוח טכני. Finchat לניתוח פונדמנטלי עם AI. TradingView לסוחרים; Finchat למשקיעים שמנתחים חברות."}, {"q": "TradingView חינמי?", "a": "TradingView מציע תוכנית חינמית עם 3 אינדיקטורים; Essential מ-$14.95/חודש. Finchat מציע תוכנית חינמית; Pro ב-$30/חודש."}, {"q": "מה זה Pine Script?", "a": "Pine Script היא שפת התכנות של TradingView לכתיבת אינדיקטורים מותאמים אישית ואסטרטגיות מסחר. הקהילה משתפת אלפי scripts חינם."}, {"q": "TradingView לישראל – האם זה תקין?", "a": "TradingView תומך במניות ת\"א, Tel Aviv 35 ומניות ישראליות נוספות. נתוני זמן אמת לבורסת ת\"א דורשים subscription מתאים."}]$t16fq$::JSONB WHERE slug = 'fiscal-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t17ci$["✅ אתם רוצים ליצור מצגת AI מפרומפט בדקות עם עיצוב מודרני", "✅ Gamma מייצר תוכן ועיצוב – לא רק תבניות", "✅ שיתוף כקישור web ללא קבצי PowerPoint", "✅ Gamma חינמי יותר בכניסה מ-Prezi"]$t17ci$::JSONB, faq = $t17fq$[{"q": "Gamma לעומת Prezi – מה עדיף?", "a": "Gamma מהיר יותר עם AI generation ומצגות web. Prezi ייחודי עם Canvas zooming. Gamma לעיצוב מהיר; Prezi להצגה חיה מרשימה."}, {"q": "Prezi חינמי?", "a": "Prezi מציע תוכנית חינמית עם 5 מצגות; Premium מ-$7/חודש. Gamma חינמי עם 400 נקודות AI; Plus ב-$10/חודש."}, {"q": "Gamma תומך בעברית?", "a": "כן, Gamma מבין פרומפטים בעברית. שימו לב שה-RTL של עברית עשוי לדרוש התאמות ידניות בפריסת השקפים."}, {"q": "Prezi לעומת PowerPoint – מה עדיף?", "a": "Prezi ייחודי ומרשים יותר ויזואלית. PowerPoint אוניברסלי וקל יותר לשיתוף. Prezi לעוצמה ויזואלית; PowerPoint לתאימות."}]$t17fq$::JSONB WHERE slug = 'gamma' AND lang = 'he';
