UPDATE tools SET choose_if = $t28ci$["✅ אתם רוצים כלי Terminal AI פתוח שעובד עם מודלים שונים", "✅ OpenCode תומך ב-OpenAI, Anthropic ומודלים מקומיים", "✅ חינמי ו-Open Source – ללא subscription לכלי עצמו", "✅ חוויה כמו Claude Code ללא תלות אקסקלוסיבית ב-Anthropic"]$t28ci$::JSONB, faq = $t28fq$[{"q": "מה זה OpenCode?", "a": "OpenCode הוא עוזר קוד Terminal פתוח בדומה ל-Claude Code. תומך במודלים מרובים – OpenAI, Anthropic, Ollama."}, {"q": "OpenCode לעומת Claude Code – מה עדיף?", "a": "Claude Code חזק יותר עם מיטוב ל-Anthropic. OpenCode גמיש יותר וחינמי. Anthropic Max ל-Claude Code; גמישות – OpenCode."}, {"q": "Claude Code חינמי?", "a": "Claude Code CLI חינמי. משלמים עבור API לפי tokens. שימוש אינטנסיבי – Claude Max ($100/חודש) כולל API usage."}, {"q": "OpenCode עם מודלים מקומיים?", "a": "כן, OpenCode תומך ב-Ollama. זה מאפשר Coding Assistance מקומי לחלוטין ופרטי. האיכות תלויה בגודל המודל המקומי."}]$t28fq$::JSONB WHERE slug = 'opencode' AND lang = 'he';
UPDATE tools SET choose_if = $t29ci$["✅ אתם צריכים תמלול בזמן אמת בפגישות Zoom ו-Teams", "✅ Otter.ai מציג כתוביות חיות וסיכום אוטומטי", "✅ חיפוש בתמלולים קודמים והקלטות", "✅ ממשק מוכן לשימוש ללא פיתוח"]$t29ci$::JSONB, faq = $t29fq$[{"q": "Whisper לעומת Otter.ai?", "a": "Whisper Open Source API לפיתוחים. Otter.ai מוצר מוכן לשימוש לפגישות. Whisper למפתחים; Otter.ai לאנשי עסקים."}, {"q": "Whisper חינמי?", "a": "Whisper Open Source חינמי לחלוטין. OpenAI Whisper API ב-$0.006/דקה. Otter.ai מציע 300 דקות חינם; Pro ב-$16.99/חודש."}, {"q": "Whisper לעברית – כמה מדויק?", "a": "Whisper מדויק מאוד לעברית – אחד המודלים הטובים ביותר לתמלול עברי. Large V3 מציע דיוק מצוין לעברית."}, {"q": "Otter.ai לעברית?", "a": "Otter.ai בעיקרו לאנגלית. תמיכה בעברית מוגבלת. לתמלול עברי מדויק – Whisper API עם מודלים מקומיים עדיף."}]$t29fq$::JSONB WHERE slug = 'otter-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t30ci$["✅ אתם יוצרים Investor Decks ומצגות מכירה עם Analytics", "✅ Pitch Analytics: ראו מי פתח את ה-Deck וכמה זמן צפה בכל שקף", "✅ templates מקצועיים לסטארטאפים ו-Business Pitches", "✅ עבודת צוות מתקדמת – Live Editing, הערות ו-Version History"]$t30ci$::JSONB, faq = $t30fq$[{"q": "Beautiful.ai לעומת Pitch לסטארטאפים?", "a": "Pitch מועדף לגיוס כסף – templates לסטארטאפ ו-Analytics. Beautiful.ai לצוותי שיווק עם Brand. Pitch לגיוס; Beautiful.ai למצגות שיווקיות."}, {"q": "Beautiful.ai חינמי?", "a": "Beautiful.ai אין תוכנית חינמית קבועה; Pro ב-$12/חודש. Pitch חינמי עד 3 חברים; Pro ב-$8/חבר/חודש."}, {"q": "Beautiful.ai Brand – כיצד זה עובד?", "a": "Beautiful.ai מאפשר להגדיר צבעי Brand, פונות ולוגו. כל המצגות של הצוות ישתמשו בהגדרות אלה אוטומטית. מועיל מאוד לצוותי Marketing."}, {"q": "Pitch לעומת Google Slides?", "a": "Pitch יפה יותר עם templates מודרניים ו-Analytics. Google Slides חינמי לחלוטין ועובד עם Workspace. Pitch לסטארטאפים; Slides לעבודה יומיומית."}]$t30fq$::JSONB WHERE slug = 'pitch' AND lang = 'he';
