UPDATE tools SET choose_if = $t36ci$["✅ אתם רוצים לוד templates מקצועיים ל-PowerPoint ו-Google Slides", "✅ אלפי תבניות נושאיות לכל אירוע וצורך", "✅ Slidesgo AI מייצר מצגת מותאמת ישירות ב-Google Slides", "✅ אתם עובדים ב-PowerPoint ורוצים רק template איכותי"]$t36ci$::JSONB, faq = $t36fq$[{"q": "Slidesgo לעומת Gamma – מה עדיף?", "a": "Slidesgo לתבניות ב-Google Slides ו-PowerPoint. Gamma ליצירה מלאה מ-AI. Slidesgo לעובדי Google Slides; Gamma לאלה שרוצים AI מלא."}, {"q": "Slidesgo חינמי?", "a": "Slidesgo מציע templates חינמיים; Premium מ-$8.25/חודש. Gamma חינמי עם 400 נקודות; Plus ב-$10/חודש."}, {"q": "Slidesgo AI לעומת Gamma AI?", "a": "Slidesgo AI מייצר template ב-Google Slides. Gamma AI מייצר תוכן ועיצוב מלאים. Slidesgo ל-template; Gamma לגנרציה מלאה."}, {"q": "Slidesgo לעברית?", "a": "Slidesgo מציע templates שניתן להוסיף להם טקסט עברי. ה-RTL דורש התאמה ידנית ב-Google Slides. Gamma גם מבין עברית אך RTL עשוי לדרוש התאמות."}]$t36fq$::JSONB WHERE slug = 'slidesgo' AND lang = 'he';
UPDATE tools SET choose_if = $t37ci$["✅ אתם תלמידים שצריכים עזרה מהירה בשיעורי בית בצילום השאלה", "✅ Socratic מ-Google מזהה שאלה בצילום ומספק הסבר מיידי", "✅ חינמי לחלוטין ללא הגבלה", "✅ מכסה מתמטיקה, מדעים, היסטוריה ושפות"]$t37ci$::JSONB, faq = $t37fq$[{"q": "Socratic לעומת Khanmigo?", "a": "Socratic חינמי ומהיר לתשובות. Khanmigo מנחה ומפתח חשיבה. לתשובה מהירה – Socratic; לחינוך ולפדגוגיה – Khanmigo."}, {"q": "Socratic חינמי?", "a": "כן, Socratic חינמי לחלוטין ללא Subscription. Khanmigo ב-$9/חודש."}, {"q": "Socratic לעברית?", "a": "Socratic תומך במספר שפות אך מיטבי לאנגלית. שאלות בעברית עשויות לעבוד חלקית. לתמיכה בעברית מלאה, Claude או ChatGPT עדיפים."}, {"q": "Socratic עובד ב-Android ו-iOS?", "a": "כן, Socratic זמין כאפליקציה ל-Android ול-iOS. מאפשר צילום שאלה ישירות מהמצלמה לזיהוי ופתרון."}]$t37fq$::JSONB WHERE slug = 'socratic-by-google' AND lang = 'he';
UPDATE tools SET choose_if = $t38ci$["✅ אתם מחפשים ממשק פשוט יותר ל-Stable Diffusion עם UI קלאסי", "✅ Auto1111 מוכר ולו ecosystem גדול של Extensions", "✅ קל יותר להתחיל ל-SD בלי ללמוד Node-based Workflow", "✅ יש tutorials רבים ותמיכת קהילה למתחילים"]$t38ci$::JSONB, faq = $t38fq$[{"q": "ComfyUI לעומת Auto1111 – מה עדיף?", "a": "ComfyUI חזק יותר ל-Workflows מורכבים ומהיר יותר. Auto1111 פשוט יותר למתחילים. ComfyUI לאנשי מקצוע; Auto1111 להתחלה."}, {"q": "ComfyUI חינמי?", "a": "כן, ComfyUI ו-Auto1111 שניהם Open Source וחינמיים. דורשים GPU מתאים. שירותי ענן זמינים בעלות."}, {"q": "FLUX לעומת Stable Diffusion?", "a": "FLUX (מ-Black Forest Labs) מייצר תמונות איכותיות יותר ממודלי SD ישנים. ComfyUI תומך ב-FLUX. FLUX נחשב לאחד מהמודלים הפתוחים הטובים ביותר כיום."}, {"q": "ComfyUI ל-macOS Apple Silicon?", "a": "ComfyUI עובד על Apple Silicon (M1/M2/M3) עם MPS backend. ביצועים טובים בהשוואה ל-CPU. לביצועים מיטביים – GPU NVIDIA עדיין עדיף."}]$t38fq$::JSONB WHERE slug = 'stable-diffusion' AND lang = 'he';
UPDATE tools SET choose_if = $t39ci$["✅ אתם רוצים AI שמייצר אוטומטית אותות מסחר וזיהוי דפוסים", "✅ Tickeron AI Robots מייצרים המלצות קנייה ומכירה אוטומטיות", "✅ גישה מבוססת AI ללא ניתוח טכני ידני", "✅ מתחילים שמעדיפים הנחיית AI למסחר"]$t39ci$::JSONB, faq = $t39fq$[{"q": "מה זה Tickeron?", "a": "Tickeron פלטפורמת מסחר AI שמזהה דפוסי מסחר, מייצרת אותות ומציעה AI Robots לאוטומציה. משלב ניתוח טכני עם AI."}, {"q": "Tickeron לעומת TradingView – למתחילים?", "a": "Tickeron ידידותי יותר למתחילים עם אותות AI. TradingView דורש ידע בניתוח טכני. אך TradingView חינמי ומצוין לקריאת גרפים בסיסית."}, {"q": "אותות Tickeron – כמה הם אמינים?", "a": "כלי אותות AI אינם מובטחים. Tickeron מציג ביצועים היסטוריים של הדפוסים. ניתן להשתמש בו כאחד מכלי הניתוח ולא כבסיס יחיד להחלטות."}, {"q": "Tickeron כמה עולה?", "a": "Tickeron מ-$90/חודש לתכניות בסיסיות. TradingView מציע תוכנית חינמית; Essential מ-$14.95/חודש."}]$t39fq$::JSONB WHERE slug = 'tickeron' AND lang = 'he';
UPDATE tools SET choose_if = $t40ci$["✅ אתם סוחרים טכניים שצריכים גרפים מתקדמים, אינדיקטורים ו-Pine Script", "✅ קהילת מסחר ענקית עם רעיונות, ניתוחים ו-scripts", "✅ נתוני זמן אמת ואינטגרציה עם brokers", "✅ סוגי נכסים רבים – מניות, קריפטו, פורקס, חוזים"]$t40ci$::JSONB, faq = $t40fq$[{"q": "TradingView לעומת Finchat – מה ההבדל?", "a": "TradingView לניתוח טכני. Finchat לניתוח פונדמנטלי עם AI. TradingView לסוחרים; Finchat למשקיעים שמנתחים חברות."}, {"q": "TradingView חינמי?", "a": "TradingView מציע תוכנית חינמית עם 3 אינדיקטורים; Essential מ-$14.95/חודש. Finchat מציע תוכנית חינמית; Pro ב-$30/חודש."}, {"q": "מה זה Pine Script?", "a": "Pine Script היא שפת התכנות של TradingView לכתיבת אינדיקטורים מותאמים אישית ואסטרטגיות מסחר. הקהילה משתפת אלפי scripts חינם."}, {"q": "TradingView לישראל – האם זה תקין?", "a": "TradingView תומך במניות ת\"א, Tel Aviv 35 ומניות ישראליות נוספות. נתוני זמן אמת לבורסת ת\"א דורשים subscription מתאים."}]$t40fq$::JSONB WHERE slug = 'tradingview' AND lang = 'he';
UPDATE tools SET choose_if = $t41ci$["✅ אתם רוצים AI לניתוח מגמות שוק וזיהוי דפוסי מחיר אוטומטי", "✅ Uptrends AI מזהה מגמות מתעוררות במניות ובשווקים", "✅ אותות AI ללא ניתוח טכני עמוק", "✅ התראות כשמזוהות מגמות חדשות"]$t41ci$::JSONB, faq = $t41fq$[{"q": "מה זה Uptrends AI?", "a": "Uptrends AI כלי השקעות AI שמנתח מגמות שוק ומזהה הזדמנויות השקעה באמצעות Machine Learning."}, {"q": "Uptrends AI לעומת Koyfin – מי עדיף?", "a": "Koyfin בוגר יותר לניתוח פונדמנטלי ולניהול תיק. Uptrends AI מתמחה באותות מגמה. Koyfin למשקיעים פונדמנטליים; Uptrends לאותות מגמה."}, {"q": "Uptrends AI לקריפטו?", "a": "Uptrends AI מכסה מחלקות נכסים שונות. בדקו את הפלטפורמה לרשימת הנכסים הנתמכים."}, {"q": "Koyfin למשקיעים ישראלים?", "a": "Koyfin מכסה שווקים בינלאומיים. למניות ת\"א יש כיסוי חלקי. עבור ניתוח שוק ישראלי ייעודי, פלטפורמות ישראליות עשויות להיות טובות יותר."}]$t41fq$::JSONB WHERE slug = 'uptrends-ai' AND lang = 'he';
UPDATE tools SET choose_if = $t42ci$["✅ אתם מפתחים שרוצים תמלול מדויק מאוד ב-API חינמי ופתוח", "✅ Whisper Open Source – ניתן להריץ מקומית ללא עלות", "✅ תמיכה בעברית ובעשרות שפות ברמה גבוהה", "✅ מתאים לאינטגרציה בפרויקטים ואפליקציות"]$t42ci$::JSONB, faq = $t42fq$[{"q": "Whisper לעומת Otter.ai?", "a": "Whisper Open Source API לפיתוחים. Otter.ai מוצר מוכן לשימוש לפגישות. Whisper למפתחים; Otter.ai לאנשי עסקים."}, {"q": "Whisper חינמי?", "a": "Whisper Open Source חינמי לחלוטין. OpenAI Whisper API ב-$0.006/דקה. Otter.ai מציע 300 דקות חינם; Pro ב-$16.99/חודש."}, {"q": "Whisper לעברית – כמה מדויק?", "a": "Whisper מדויק מאוד לעברית – אחד המודלים הטובים ביותר לתמלול עברי. Large V3 מציע דיוק מצוין לעברית."}, {"q": "Otter.ai לעברית?", "a": "Otter.ai בעיקרו לאנגלית. תמיכה בעברית מוגבלת. לתמלול עברי מדויק – Whisper API עם מודלים מקומיים עדיף."}]$t42fq$::JSONB WHERE slug = 'whisper' AND lang = 'he';
UPDATE tools SET choose_if = $t43ci$["✅ אתם מעדיפים מהירות – Zed כתוב ב-Rust ונשאר מהיר גם בפרויקטים גדולים", "✅ Multiplayer נייטיב – כמה מפתחים בעורך אחד בזמן אמת", "✅ שילוב AI עם Claude לניתוח ויצירת קוד", "✅ עורך נקי ופשוט למפתחים שמעדיפים מינימליזם"]$t43ci$::JSONB, faq = $t43fq$[{"q": "Zed לעומת Cursor – מה עדיף?", "a": "Cursor בוגר יותר עם Agentic Features חזקים. Zed מהיר יותר עם Multiplayer ייחודי. AI Coding – Cursor; ביצועים ושיתוף – Zed."}, {"q": "Zed חינמי?", "a": "Zed חינמי ו-Open Source. AI Features ב-Zed עשויים לדרוש API. Cursor מציע תוכנית חינמית; Pro ב-$20/חודש."}, {"q": "Zed Extensions – האם יש?", "a": "Zed לא תואם ל-VS Code Extensions. יש ל-Zed system Extensions משלו שעדיין קטן ממערכת VS Code. גדל בהדרגה."}, {"q": "Zed ל-macOS – כמה מוטב?", "a": "Zed פותח במקור ל-macOS ומשתמש ב-Metal API לביצועים מיטביים. Linux נתמך; Windows בפיתוח."}]$t43fq$::JSONB WHERE slug = 'zed' AND lang = 'he';
